target = '.......((.((.((....)).((...))...)))).((.((.((....)).((...))...)))).((.((.((....)).((...))...)))).......'
def dist(s): return RNA.bp_distance(RNA.fold_compound(s).mfe()[0], target)
def folds_to(s): return RNA.fold_compound(s).mfe()[0] == target

seeds = [
 'AAAAAAAGGACCACCGAAAGGAGCAGAGCAGAGGCCAGGACCAGGGAAACCAGCGCAGCAACGGCCAGGACCAGGAUCACCAGCAUAGCAUAGGCCAAAAAAA',
 'GGAUUAAGAAGACCCAUAAGGAGCACAGCAACGACCAGGACCAGGAGACCCAGCAAAGCACAGGCCAAGAUUAGGAAAACCAGCAGAGCACGAGACACCCGAG',
]

def worker(seed_seq):
    random.seed(hash(seed_seq) & 0xffffffff)
    cur = seed_seq
    cur_d = dist(cur)
    best, best_d = cur, cur_d
    deadline = time.time() + 100
    while time.time() < deadline:
        c = list(cur)
        for _ in range(random.choice([1,1,2,3])):
            i = random.randrange(len(c)); c[i] = random.choice('ACGU')
        c = ''.join(c); d = dist(c)
